package com.raidingdamage;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import net.runelite.client.util.QuantityFormatter;

public final class Format
{
	private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm");
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);

	private Format()
	{
	}

	public static String number(int value)
	{
		return QuantityFormatter.formatNumber(value);
	}

	/**
	 * Short form for infoboxes: 9,876 stays exact, 12,345 becomes 12.3k.
	 */
	public static String compact(int value)
	{
		if (value < 10_000)
		{
			return Integer.toString(value);
		}
		return String.format(Locale.ROOT, "%.1fk", value / 1000.0);
	}

	public static String percent(double share)
	{
		return String.format(Locale.ROOT, "%.1f%%", share * 100);
	}

	/**
	 * Game ticks as m:ss.s
	 */
	public static String ticks(int ticks)
	{
		int tenths = ticks * 6;
		return String.format(Locale.ROOT, "%d:%02d.%d", tenths / 600, tenths % 600 / 10, tenths % 10);
	}

	public static String duration(long millis)
	{
		long seconds = Math.max(0, millis / 1000);
		if (seconds >= 3600)
		{
			return String.format(Locale.ROOT, "%d:%02d:%02d", seconds / 3600, seconds % 3600 / 60, seconds % 60);
		}
		return String.format(Locale.ROOT, "%d:%02d", seconds / 60, seconds % 60);
	}

	public static String date(long epochMillis)
	{
		ZonedDateTime time = Instant.ofEpochMilli(epochMillis).atZone(ZoneId.systemDefault());
		LocalDate today = LocalDate.now(ZoneId.systemDefault());
		LocalDate day = time.toLocalDate();
		String prefix;
		if (day.equals(today))
		{
			prefix = "Today";
		}
		else if (day.equals(today.minusDays(1)))
		{
			prefix = "Yesterday";
		}
		else
		{
			prefix = DATE.format(time);
		}
		return prefix + " " + TIME.format(time);
	}
}

package com.raidingdamage;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(RaidingDamageConfig.GROUP)
public interface RaidingDamageConfig extends Config
{
	String GROUP = "raiding-damage";

	@ConfigSection(
		name = "Damage tracker",
		description = "Per-room damage tracking for ToB, ToA, CoX and TFA",
		position = 0
	)
	String damageSection = "damageSection";

	@ConfigSection(
		name = "Damage infoboxes",
		description = "Live damage infoboxes shown while in a raid",
		position = 1
	)
	String infoboxSection = "infoboxSection";

	@ConfigItem(
		keyName = "trackTob",
		name = "Theatre of Blood",
		description = "Track damage in the Theatre of Blood",
		section = damageSection,
		position = 0
	)
	default boolean trackTob()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackToa",
		name = "Tombs of Amascut",
		description = "Track damage in the Tombs of Amascut",
		section = damageSection,
		position = 1
	)
	default boolean trackToa()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackCox",
		name = "Chambers of Xeric",
		description = "Track damage in the Chambers of Xeric",
		section = damageSection,
		position = 2
	)
	default boolean trackCox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackTfa",
		name = "The Fractured Archive",
		description = "Track damage in The Fractured Archive",
		section = damageSection,
		position = 3
	)
	default boolean trackTfa()
	{
		return true;
	}

	@ConfigItem(
		keyName = "shareWithParty",
		name = "Share with party",
		description = "Send your damage to your RuneLite party, so everyone using this plugin can see exactly who did what."
			+ " Without a party, other players' damage is grouped together as 'Others'.",
		section = damageSection,
		position = 4
	)
	default boolean shareWithParty()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bossDamageOnly",
		name = "Boss damage only",
		description = "Count only damage dealt to the room's boss in chat summaries and infoboxes."
			+ " The side panel has its own toggle.",
		section = damageSection,
		position = 5
	)
	default boolean bossDamageOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "roomChatSummary",
		name = "Room summary in chat",
		description = "Post your damage and share in the chatbox when a room is completed",
		section = damageSection,
		position = 6
	)
	default boolean roomChatSummary()
	{
		return true;
	}

	@ConfigItem(
		keyName = "raidChatSummary",
		name = "Raid summary in chat",
		description = "Post your total damage and share in the chatbox when you leave a raid",
		section = damageSection,
		position = 7
	)
	default boolean raidChatSummary()
	{
		return true;
	}

	@Range(min = 1, max = 500)
	@ConfigItem(
		keyName = "historySize",
		name = "Raids to keep",
		description = "How many completed raids to keep in the side panel history",
		section = damageSection,
		position = 8
	)
	default int historySize()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "roomDamageInfobox",
		name = "Room damage",
		description = "Show your damage in the current room",
		section = infoboxSection,
		position = 0
	)
	default boolean roomDamageInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "roomShareInfobox",
		name = "Room share",
		description = "Show your percentage of the current room's damage",
		section = infoboxSection,
		position = 1
	)
	default boolean roomShareInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "raidDamageInfobox",
		name = "Raid damage",
		description = "Show your total damage across the whole raid",
		section = infoboxSection,
		position = 2
	)
	default boolean raidDamageInfobox()
	{
		return false;
	}
}

package com.raidingdamage;

import com.google.inject.Provides;
import com.raidingdamage.damage.DamageHistory;
import com.raidingdamage.damage.DamageTracker;
import com.raidingdamage.ui.Icons;
import com.raidingdamage.ui.RaidingDamagePanel;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Raiding Damage",
	description = "Per-room damage tracking for ToB, ToA, CoX and TFA, with party comparison",
	tags = {"raid", "raids", "tob", "toa", "cox", "tfa", "theatre", "tombs", "chambers", "fractured", "archive", "damage", "dps"},
	internalName = "raiding-damage"
)
public class RaidingDamagePlugin extends Plugin
{
	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private EventBus eventBus;

	@Inject
	private DamageTracker damageTracker;

	@Inject
	private DamageHistory damageHistory;

	private RaidingDamagePanel panel;
	private NavigationButton navButton;

	@Override
	protected void startUp() throws Exception
	{
		panel = injector.getInstance(RaidingDamagePanel.class);
		navButton = NavigationButton.builder()
			.tooltip("Raiding Damage")
			.icon(Icons.navIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		final RaidingDamagePanel p = panel;
		damageHistory.load(getPluginDirectory(), raids -> SwingUtilities.invokeLater(() -> p.setHistory(raids)));
		damageTracker.startUp(this, raid -> SwingUtilities.invokeLater(() -> p.setLive(raid)));
		eventBus.register(damageTracker);
	}

	@Override
	protected void shutDown() throws Exception
	{
		eventBus.unregister(damageTracker);
		damageTracker.shutDown();
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (RaidingDamageConfig.GROUP.equals(event.getGroup()) && event.getKey().startsWith("track"))
		{
			final RaidingDamagePanel p = panel;
			SwingUtilities.invokeLater(p::updateRaidFilters);
		}
	}

	@Provides
	RaidingDamageConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RaidingDamageConfig.class);
	}
}

package com.raidingdamage.damage;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Who dealt what share of a room's (or a whole raid's) damage.
 * <p>
 * Named entries are players whose damage is known: the local player, party members sharing their
 * damage, and - when only one teammate isn't sharing - that teammate, since every hit that wasn't
 * the local player's or a party member's must be theirs. Whatever is left is grouped as "Others".
 */
@Value
public class DamageBreakdown
{
	public static final String OTHERS = "Others";

	List<Entry> entries;
	int total;

	@Value
	public static class Entry
	{
		String name;
		int damage;
		double share;
		boolean local;
		boolean others;
		/**
		 * Damage worked out by elimination rather than reported directly.
		 */
		boolean inferred;
		/**
		 * Teammates making up an "Others" entry, if known.
		 */
		List<String> members;
		/**
		 * Highest damage. Only given when it's certain, i.e. no single unknown player could have
		 * done more.
		 */
		boolean top;

		public int getPlayerCount()
		{
			return others ? members.size() : 1;
		}
	}

	public Entry getLocal()
	{
		for (Entry entry : entries)
		{
			if (entry.local)
			{
				return entry;
			}
		}
		return null;
	}

	public Entry getOthers()
	{
		for (Entry entry : entries)
		{
			if (entry.others)
			{
				return entry;
			}
		}
		return null;
	}

	public int getNamedCount()
	{
		int count = 0;
		for (Entry entry : entries)
		{
			if (!entry.others)
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * 1-based rank of the local player among named players, or 0 if they dealt no damage.
	 */
	public int getLocalRank()
	{
		int rank = 0;
		for (Entry entry : entries)
		{
			if (!entry.others)
			{
				rank++;
				if (entry.local)
				{
					return rank;
				}
			}
		}
		return 0;
	}

	public static DamageBreakdown ofRoom(RoomRecord room, String localName, boolean bossOnly)
	{
		Map<String, Integer> named = new LinkedHashMap<>();
		room.getPlayers().forEach((name, dmg) -> named.put(name, dmg.get(bossOnly)));
		int others = Math.max(0, room.getDamage(bossOnly) - sum(named.values()));
		return build(named, others, unnamed(room, localName), localName);
	}

	public static DamageBreakdown ofRaid(RaidRecord raid, boolean bossOnly)
	{
		Map<String, Integer> named = new LinkedHashMap<>();
		Set<String> unnamed = new LinkedHashSet<>();
		int others = 0;
		for (RoomRecord room : raid.getRooms())
		{
			int roomNamed = 0;
			for (Map.Entry<String, PlayerDamage> e : room.getPlayers().entrySet())
			{
				int dmg = e.getValue().get(bossOnly);
				named.merge(e.getKey(), dmg, Integer::sum);
				roomNamed += dmg;
			}
			others += Math.max(0, room.getDamage(bossOnly) - roomNamed);
			unnamed.addAll(unnamed(room, raid.getLocalName()));
		}
		unnamed.removeAll(named.keySet());
		return build(named, others, unnamed, raid.getLocalName());
	}

	/**
	 * Teammates in the room whose damage isn't known directly.
	 */
	private static Set<String> unnamed(RoomRecord room, String localName)
	{
		Set<String> unnamed = new LinkedHashSet<>(room.getTeam());
		unnamed.removeAll(room.getPlayers().keySet());
		unnamed.remove(localName);
		return unnamed;
	}

	private static DamageBreakdown build(Map<String, Integer> named, int others, Set<String> unnamed, String localName)
	{
		String inferred = null;
		if (unnamed.size() == 1)
		{
			inferred = unnamed.iterator().next();
			named.merge(inferred, others, Integer::sum);
			others = 0;
		}

		int total = sum(named.values()) + others;
		int max = 0;
		for (int dmg : named.values())
		{
			max = Math.max(max, dmg);
		}

		List<Map.Entry<String, Integer>> sorted = new ArrayList<>(named.entrySet());
		sorted.sort(Collections.reverseOrder(Map.Entry.comparingByValue()));

		List<Entry> entries = new ArrayList<>(sorted.size() + 1);
		for (Map.Entry<String, Integer> e : sorted)
		{
			String name = e.getKey();
			int dmg = e.getValue();
			boolean top = dmg > 0 && dmg == max && dmg >= others;
			entries.add(new Entry(name, dmg, share(dmg, total), name.equals(localName), false,
				name.equals(inferred), Collections.emptyList(), top));
		}
		if (others > 0 || unnamed.size() > 1)
		{
			String name = unnamed.size() > 1 ? unnamed.size() + " others" : OTHERS;
			List<String> members = unnamed.size() > 1 ? new ArrayList<>(unnamed) : Collections.emptyList();
			entries.add(new Entry(name, others, share(others, total), false, true, false, members, false));
		}
		return new DamageBreakdown(entries, total);
	}

	private static double share(int damage, int total)
	{
		return total == 0 ? 0 : (double) damage / total;
	}

	private static int sum(Collection<Integer> values)
	{
		int sum = 0;
		for (int v : values)
		{
			sum += v;
		}
		return sum;
	}
}

package com.raidingdamage.damage;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.Reader;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Completed raids, newest first, persisted as JSON in the plugin's data directory.
 * Disk IO runs on the executor; all methods are safe to call from any thread.
 */
@Slf4j
@Singleton
public class DamageHistory
{
	private static final String FILE_NAME = "damage-history.json";

	private final Gson gson;
	private final ScheduledExecutorService executor;

	private final List<RaidRecord> raids = new ArrayList<>();
	private Filepath file;
	private Consumer<List<RaidRecord>> listener = r -> {};

	@Inject
	DamageHistory(Gson gson, ScheduledExecutorService executor)
	{
		this.gson = gson;
		this.executor = executor;
	}

	public void load(Filepath directory, Consumer<List<RaidRecord>> listener)
	{
		synchronized (this)
		{
			this.file = directory.join(FILE_NAME);
			this.listener = listener;
		}
		executor.execute(this::read);
	}

	public void add(RaidRecord raid, int limit)
	{
		synchronized (this)
		{
			raids.add(0, raid);
			trim(limit);
		}
		changed();
	}

	public void remove(String id)
	{
		synchronized (this)
		{
			raids.removeIf(r -> r.getId().equals(id));
		}
		changed();
	}

	public void clear()
	{
		synchronized (this)
		{
			raids.clear();
		}
		changed();
	}

	/**
	 * Records are not modified once they're in the history, so sharing them is safe.
	 */
	public synchronized List<RaidRecord> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(raids));
	}

	private void trim(int limit)
	{
		while (raids.size() > Math.max(1, limit))
		{
			raids.remove(raids.size() - 1);
		}
	}

	private void changed()
	{
		final String json;
		final Filepath target;
		final Consumer<List<RaidRecord>> notify;
		synchronized (this)
		{
			json = gson.toJson(raids.toArray(new RaidRecord[0]));
			target = file;
			notify = listener;
		}
		notify.accept(snapshot());
		if (target != null)
		{
			executor.execute(() -> write(target, json));
		}
	}

	private void read()
	{
		Filepath target;
		synchronized (this)
		{
			target = file;
		}

		RaidRecord[] loaded = null;
		if (target.exists())
		{
			try (Reader reader = target.openBufferedReader())
			{
				loaded = gson.fromJson(reader, RaidRecord[].class);
			}
			catch (IOException | JsonParseException e)
			{
				log.warn("Unable to read raid damage history", e);
			}
		}

		Consumer<List<RaidRecord>> notify;
		synchronized (this)
		{
			if (loaded != null)
			{
				for (RaidRecord raid : loaded)
				{
					// Drop anything from a future/unknown version we can't make sense of
					if (raid != null && raid.getRaid() != null && raid.getId() != null)
					{
						raid.getRooms().removeIf(room -> room == null || room.getRoom() == null);
						// Raids added before loading finished are newer, so they stay in front
						raids.add(raid);
					}
				}
			}
			notify = listener;
		}
		notify.accept(snapshot());
	}

	private static void write(Filepath target, String json)
	{
		try
		{
			Filepath parent = target.getParent();
			parent.createDirectories();
			Filepath temp = parent.createTempFile("damage-history", ".tmp");
			temp.write(json);
			temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Unable to save raid damage history", e);
		}
	}
}

package com.raidingdamage.damage;

import java.awt.Color;
import java.awt.image.BufferedImage;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Shows a pre-formatted value. Text is computed by the tracker when damage changes, not per frame.
 */
class DamageInfoBox extends InfoBox
{
	enum Kind
	{
		ROOM_DAMAGE,
		ROOM_SHARE,
		RAID_DAMAGE,
	}

	@Getter
	private final Kind kind;
	@Setter
	private volatile String text = "";
	@Setter
	private volatile Color textColor = Color.WHITE;

	DamageInfoBox(Kind kind, BufferedImage image, Plugin plugin)
	{
		super(image, plugin);
		this.kind = kind;
	}

	@Override
	public String getText()
	{
		return text;
	}

	@Override
	public Color getTextColor()
	{
		return textColor;
	}

	@Override
	public String getName()
	{
		return super.getName() + "_" + kind.name();
	}
}

