@Getter
public enum RaidRoom
{
	// Theatre of Blood - identified by region
	MAIDEN(RaidType.TOB, "Maiden", regions(12613), "The Maiden of Sugadinti"),
	BLOAT(RaidType.TOB, "Bloat", regions(13125), "Pestilent Bloat"),
	NYLOCAS(RaidType.TOB, "Nylocas", regions(13122), "Nylocas Vasilias", "Nylocas Prinkipas"),
	SOTETSEG(RaidType.TOB, "Sotetseg", regions(13123, 13379), "Sotetseg"),
	XARPUS(RaidType.TOB, "Xarpus", regions(12612), "Xarpus"),
	VERZIK(RaidType.TOB, "Verzik", regions(12611), "Verzik Vitur"),

	// Tombs of Amascut - identified by region
	CRONDIS(RaidType.TOA, "Path of Crondis", regions(15698)),
	ZEBAK(RaidType.TOA, "Zebak", regions(15700), "Zebak"),
	SCABARAS(RaidType.TOA, "Path of Scabaras", regions(14162)),
	KEPHRI(RaidType.TOA, "Kephri", regions(14164), "Kephri"),
	APMEKEN(RaidType.TOA, "Path of Apmeken", regions(15186)),
	BABA(RaidType.TOA, "Ba-Ba", regions(15188), "Ba-Ba"),
	HET(RaidType.TOA, "Path of Het", regions(14674)),
	AKKHA(RaidType.TOA, "Akkha", regions(14676), "Akkha"),
	WARDENS(RaidType.TOA, "Wardens", regions(15184, 15696), "Obelisk", "Elidinis' Warden", "Tumeken's Warden", "Core"),

	// Chambers of Xeric - the layout is random, so rooms are identified by the NPC being hit
	TEKTON(RaidType.COX, "Tekton", npcs("Tekton"), "Tekton"),
	VASA(RaidType.COX, "Vasa Nistirio", npcs("Vasa Nistirio", "Glowing crystal"), "Vasa Nistirio"),
	VANGUARDS(RaidType.COX, "Vanguards", npcs("Vanguard"), "Vanguard"),
	MUTTADILES(RaidType.COX, "Muttadiles", npcs("Muttadile"), "Muttadile"),
	SHAMANS(RaidType.COX, "Shamans", npcs("Lizardman shaman"), "Lizardman shaman"),
	MYSTICS(RaidType.COX, "Mystics", npcs("Skeletal Mystic"), "Skeletal Mystic"),
	GUARDIANS(RaidType.COX, "Guardians", npcs("Guardian"), "Guardian"),
	ICE_DEMON(RaidType.COX, "Ice Demon", npcs("Ice demon"), "Ice demon"),
	VESPULA(RaidType.COX, "Vespula", npcs("Vespula", "Lux grub", "Vespine soldier", "Abyssal portal"), "Vespula", "Abyssal portal"),
	ROPE(RaidType.COX, "Rope", npcs("Deathly ranger", "Deathly mage"), "Deathly ranger", "Deathly mage"),
	SCAVENGERS(RaidType.COX, "Scavengers", npcs("Scavenger beast"), "Scavenger beast"),
	OLM(RaidType.COX, "Great Olm", npcs("Great Olm"), "Great Olm", "Great Olm Left Claw", "Great Olm Right Claw"),
	COX_OTHER(RaidType.COX, "Other", npcs()),

	// The Fractured Archive - identified by region; bosses by NPC id
	ARCHIVE_GUARDIAN(RaidType.TFA, "Archive Guardian", regions(16471), ids(NpcID.TFA_GUARDIAN, NpcID.TFA_GUARDIAN_UNSHIELDED)),
	EZEKIEL(RaidType.TFA, "Ezekiel", regions(16214), ids(NpcID.TFA_EZEKIEL)),
	BORK(RaidType.TFA, "Bork & Smork", regions(16727), ids(NpcID.TFA_BORK, NpcID.TFA_SMORK)),
	MOIA(RaidType.TFA, "Moia", regions(16216), ids(NpcID.TFA_MOIA)),
	DREADNOTH(RaidType.TFA, "Dreadnoth", regions(16728), ids(NpcID.TFA_JELLY_BOSS)),
	DAGONHAI(RaidType.TFA, "Dagon'hai Elder", regions(16215), ids(NpcID.TFA_DAGONHAI_LEADER, NpcID.TFA_DAGONHAI_LEADER_UNSHIELDED)),
	XARTH(RaidType.TFA, "Xarth", regions(16726), ids(NpcID.TFA_XARTH)),
	OCELLUS(RaidType.TFA, "Ocellus", regions(16472), ids(NpcID.TFA_OCELLUS_P1, NpcID.TFA_OCELLUS_P2, NpcID.TFA_OCELLUS_P3));

	private static final Map<Integer, RaidRoom> BY_REGION = new HashMap<>();

	static
	{
		for (RaidRoom room : values())
		{
			for (int region : room.regions)
			{
				BY_REGION.put(region, room);
			}
		}
	}

	private final RaidType raid;
	private final String displayName;
	@Getter(AccessLevel.NONE)
	private final int[] regions;
	@Getter(AccessLevel.NONE)
	private final String[] npcPrefixes;
	@Getter(AccessLevel.NONE)
	private final Set<String> bosses = new HashSet<>();
	@Getter(AccessLevel.NONE)
	private final Set<Integer> bossIds = new HashSet<>();

	RaidRoom(RaidType raid, String displayName, int[] regions, String... bosses)
	{
		this(raid, displayName, regions, new String[0], bosses);
	}

	RaidRoom(RaidType raid, String displayName, String[] npcPrefixes, String... bosses)
	{
		this(raid, displayName, new int[0], npcPrefixes, bosses);
	}

	RaidRoom(RaidType raid, String displayName, int[] regions, int[] bossIds)
	{
		this(raid, displayName, regions, new String[0], new String[0]);
		for (int id : bossIds)
		{
			this.bossIds.add(id);
		}
	}

	RaidRoom(RaidType raid, String displayName, int[] regions, String[] npcPrefixes, String[] bosses)
	{
		this.raid = raid;
		this.displayName = displayName;
		this.regions = regions;
		this.npcPrefixes = new String[npcPrefixes.length];
		for (int i = 0; i < npcPrefixes.length; i++)
		{
			this.npcPrefixes[i] = npcPrefixes[i].toLowerCase(Locale.ROOT);
		}
		for (String boss : bosses)
		{
			this.bosses.add(boss.toLowerCase(Locale.ROOT));
		}
	}

	public boolean isBoss(int npcId, String npcName)
	{
		return bossIds.contains(npcId) || bosses.contains(npcName.toLowerCase(Locale.ROOT));
	}

	/**
	 * The last room of the raid; its completion message means the raid was completed.
	 */
	public boolean isFinalRoom()
	{
		return this == VERZIK || this == WARDENS || this == OLM || this == OCELLUS;
	}

	public static RaidRoom forRegion(int region)
	{
		return BY_REGION.get(region);
	}

	public static RaidRoom forCoxNpc(String npcName)
	{
		String name = npcName.toLowerCase(Locale.ROOT);
		for (RaidRoom room : values())
		{
			for (String prefix : room.npcPrefixes)
			{
				if (name.startsWith(prefix))
				{
					return room;
				}
			}
		}
		return COX_OTHER;
	}

	public static RaidRoom fromKey(String key)
	{
		try
		{
			return key == null ? null : valueOf(key);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	private static int[] regions(int... regions)
	{
		return regions;
	}

	private static String[] npcs(String... names)
	{
		return names;
	}

	private static int[] ids(int... ids)
	{
		return ids;
	}
}

package com.raidingdamage.raid;

import com.raidingdamage.RaidingDamageConfig;
import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

@Getter
@RequiredArgsConstructor
public enum RaidType
{
	// Extra regions are parts of the raid with no combat room, e.g. lobbies and reward rooms
	TOB("Theatre of Blood", "ToB", ItemID.SCYTHE_OF_VITUR, new Color(0xB33A3A), new int[]{12867}),
	TOA("Tombs of Amascut", "ToA", ItemID.TUMEKENS_SHADOW, new Color(0xD9A43A), new int[]{13454, 14160, 14672}),
	COX("Chambers of Xeric", "CoX", ItemID.TWISTED_BOW, new Color(0x4E9A6B), new int[0]),
	TFA("The Fractured Archive", "TFA", ItemID.TFA_CAPE_T5, new Color(0x6A5BD6), new int[]{16474});

	private final String displayName;
	private final String shortName;
	private final int iconItemId;
	private final Color color;
	private final int[] extraRegions;

	public boolean isTracked(RaidingDamageConfig config)
	{
		switch (this)
		{
			case TOB:
				return config.trackTob();
			case TOA:
				return config.trackToa();
			case COX:
				return config.trackCox();
			case TFA:
				return config.trackTfa();
			default:
				return false;
		}
	}

	/**
	 * The raid a (template) region belongs to, or null. CoX is instanced on a random layout,
	 * so it can't be detected by region.
	 */
	public static RaidType forRegion(int region)
	{
		RaidRoom room = RaidRoom.forRegion(region);
		if (room != null)
		{
			return room.getRaid();
		}

		for (RaidType type : values())
		{
			for (int extra : type.extraRegions)
			{
				if (extra == region)
				{
					return type;
				}
			}
		}
		return null;
	}
}

package com.raidingdamage.ui;

import com.raidingdamage.Format;
import com.raidingdamage.damage.DamageBreakdown;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * One player's damage: a bar scaled against the top damage, with name, damage and share drawn over it.
 */
class DamageRow extends JComponent
{
	private static final int HEIGHT = 14;
	private static final int PAD = 4;
	private static final int STAR_SIZE = 9;

	private final String name;
	private final String value;
	private final boolean top;
	private final double fill;
	private final Color color;

	DamageRow(DamageBreakdown.Entry entry, int maxDamage, Color color)
	{
		int players = entry.getPlayerCount();
		boolean group = entry.isOthers() && players > 1;
		this.name = entry.isLocal() ? "You"
			: group ? entry.getName() + " (avg " + Math.round(entry.getShare() / players * 100) + "%)"
			: entry.getName();
		this.value = Format.number(entry.getDamage()) + "  " + Format.percent(entry.getShare());
		this.top = entry.isTop();
		this.fill = maxDamage <= 0 ? 0 : (double) entry.getDamage() / maxDamage;
		this.color = color;

		setFont(FontManager.getRunescapeSmallFont());
		setPreferredSize(new Dimension(0, HEIGHT));

		String tooltip = (entry.isLocal() ? "You (" + entry.getName() + ")" : entry.getName())
			+ ": " + Format.number(entry.getDamage()) + " damage, " + Format.percent(entry.getShare());
		if (group)
		{
			tooltip = String.join(", ", entry.getMembers()) + ": " + Format.number(entry.getDamage()) + " damage between them, "
				+ Format.percent(entry.getShare()) + " - about " + Format.number(entry.getDamage() / players)
				+ " (" + Format.percent(entry.getShare() / players) + ") each";
		}
		else if (entry.isOthers())
		{
			tooltip += " - players not sharing damage through a RuneLite party";
		}
		else if (entry.isInferred())
		{
			tooltip += " - every hit that wasn't yours or a party member's";
		}
		if (top)
		{
			tooltip += " - top damage";
		}
		setToolTipText(tooltip);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		int w = getWidth();
		int h = getHeight();

		g.setColor(Palette.BAR_BACKGROUND);
		g.fillRect(0, 0, w, h);
		g.setColor(color);
		g.fillRect(0, 0, (int) Math.round(w * fill), h);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		int baseline = (h + fm.getAscent() - fm.getDescent()) / 2;

		int valueWidth = fm.stringWidth(value);
		int valueX = w - PAD - valueWidth;
		int nameSpace = valueX - PAD * 2 - (top ? STAR_SIZE + 3 : 0);
		String shownName = fit(name, fm, nameSpace);

		drawShadowed(g, shownName, PAD, baseline);
		drawShadowed(g, value, valueX, baseline);
		if (top)
		{
			Icons.paintStar(g, PAD + fm.stringWidth(shownName) + 3, (h - STAR_SIZE) / 2, STAR_SIZE);
		}
		g.dispose();
	}

	private static void drawShadowed(Graphics2D g, String text, int x, int y)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(Color.WHITE);
		g.drawString(text, x, y);
	}

	private static String fit(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		for (int len = text.length() - 1; len > 0; len--)
		{
			String cut = text.substring(0, len) + "..";
			if (fm.stringWidth(cut) <= width)
			{
				return cut;
			}
		}
		return "";
	}
}

package com.raidingdamage.ui;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;

/**
 * Icons drawn in code, so there are no image resources to ship.
 */
public final class Icons
{
	static final Color GOLD = new Color(0xFFD24A);

	static final ImageIcon STAR = new ImageIcon(star(10));
	static final ImageIcon EXPANDED = new ImageIcon(chevron(true));
	static final ImageIcon COLLAPSED = new ImageIcon(chevron(false));

	private Icons()
	{
	}

	public static BufferedImage navIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		// One bar per raid, in its colour
		g.setColor(new Color(0xB33A3A));
		g.fillRect(0, 8, 3, 7);
		g.setColor(new Color(0xD9A43A));
		g.fillRect(4, 2, 3, 13);
		g.setColor(new Color(0x4E9A6B));
		g.fillRect(8, 5, 3, 10);
		g.setColor(new Color(0x6A5BD6));
		g.fillRect(12, 10, 3, 5);
		g.dispose();
		return image;
	}

	static void paintStar(Graphics2D g, int x, int y, int size)
	{
		Polygon star = new Polygon();
		double cx = x + size / 2.0;
		double cy = y + size / 2.0 + size * 0.05;
		double outer = size / 2.0;
		double inner = outer * 0.45;
		for (int i = 0; i < 10; i++)
		{
			double r = i % 2 == 0 ? outer : inner;
			double angle = Math.PI / 5 * i - Math.PI / 2;
			star.addPoint((int) Math.round(cx + Math.cos(angle) * r), (int) Math.round(cy + Math.sin(angle) * r));
		}
		Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(GOLD);
		g.fillPolygon(star);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa);
	}

	private static BufferedImage star(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		paintStar(g, 0, 0, size);
		g.dispose();
		return image;
	}

	private static BufferedImage chevron(boolean expanded)
	{
		BufferedImage image = new BufferedImage(9, 9, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0x9A9A9A));
		Polygon p = new Polygon();
		if (expanded)
		{
			p.addPoint(1, 2);
			p.addPoint(8, 2);
			p.addPoint(4, 7);
		}
		else
		{
			p.addPoint(2, 1);
			p.addPoint(7, 4);
			p.addPoint(2, 8);
		}
		g.fillPolygon(p);
		g.dispose();
		return image;
	}
}

package com.raidingdamage.ui;

import com.raidingdamage.damage.DamageBreakdown;
import java.awt.Color;
import java.util.HashMap;
import java.util.Map;

/**
 * Bar colours, dark enough for white text to stay readable on top.
 */
final class Palette
{
	static final Color YOU = new Color(0xB86A0C);
	static final Color OTHERS = new Color(0x4A4A4A);
	static final Color BAR_BACKGROUND = new Color(0x232323);
	private static final Color[] PARTY = {
		new Color(0x2F6DB5),
		new Color(0x3D8C4A),
		new Color(0x7B4DB5),
		new Color(0x2A8C8C),
		new Color(0xB5476F),
		new Color(0x8C7A2A),
		new Color(0x5A6E8C),
	};

	private Palette()
	{
	}

	/**
	 * Colour per player, assigned in order of raid damage so it stays the same in every room of a raid.
	 */
	static Map<String, Color> assign(DamageBreakdown raid)
	{
		Map<String, Color> colors = new HashMap<>();
		int next = 0;
		for (DamageBreakdown.Entry entry : raid.getEntries())
		{
			if (entry.isLocal())
			{
				colors.put(entry.getName(), YOU);
			}
			else if (!entry.isOthers())
			{
				colors.put(entry.getName(), PARTY[next++ % PARTY.length]);
			}
		}
		return colors;
	}

	static Color of(DamageBreakdown.Entry entry, Map<String, Color> colors)
	{
		if (entry.isOthers())
		{
			return OTHERS;
		}
		if (entry.isLocal())
		{
			return YOU;
		}
		return colors.getOrDefault(entry.getName(), PARTY[PARTY.length - 1]);
	}
}

