 */
class RaidCard extends JPanel
{
	private static final Color LIVE_COLOR = new Color(0x4CC552);
	private static final Color WIPED_COLOR = new Color(0xE0533D);
	private static final Color LEFT_COLOR = new Color(0xE0A33D);
	private static final Color SUBTLE_TEXT = new Color(0x9A9A9A);

	RaidCard(RaidRecord raid, boolean live, boolean expanded, boolean bossOnly,
		Runnable onToggle, Runnable onCopy, Runnable onDelete)
	{
		setLayout(new BorderLayout(0, 5));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, raid.getRaid().getColor()),
			new EmptyBorder(4, 5, 5, 5)));

		DamageBreakdown total = DamageBreakdown.ofRaid(raid, bossOnly);
		Map<String, Color> colors = Palette.assign(total);

		JPanel header = buildHeader(raid, live, expanded, total);
		JPanel top = new JPanel(new BorderLayout(0, 4));
		top.setOpaque(false);
		top.add(header, BorderLayout.NORTH);
		top.add(new ShareBar(total, colors), BorderLayout.SOUTH);
		add(top, BorderLayout.NORTH);

		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setToolTipText(expanded ? "Click to collapse" : "Click to show every room");
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onToggle.run();
				}
			}
		});

		JPopupMenu menu = new JPopupMenu();
		JMenuItem copy = new JMenuItem("Copy summary");
		copy.addActionListener(e -> onCopy.run());
		menu.add(copy);
		if (onDelete != null)
		{
			JMenuItem delete = new JMenuItem("Delete raid");
			delete.addActionListener(e -> onDelete.run());
			menu.add(delete);
		}
		setComponentPopupMenu(menu);
		header.setComponentPopupMenu(menu);

		if (expanded)
		{
			add(buildBody(raid, live, bossOnly, total, colors), BorderLayout.CENTER);
		}
	}

	private static JPanel buildHeader(RaidRecord raid, boolean live, boolean expanded, DamageBreakdown total)
	{
		JLabel title = new JLabel(raid.getRaid().getDisplayName());
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setIcon(expanded ? Icons.EXPANDED : Icons.COLLAPSED);
		title.setHorizontalTextPosition(SwingConstants.LEFT);
		title.setIconTextGap(4);

		String when = live
			? raid.getRooms().size() + (raid.getRooms().size() == 1 ? " room" : " rooms")
			: Format.date(raid.getStartTime()) + " - " + Format.duration(raid.getEndTime() - raid.getStartTime());
		if (!raid.getTeam().isEmpty())
		{
			when += " - " + teamSize(raid.getTeam().size() + 1);
		}
		JLabel subtitle = small(when, SUBTLE_TEXT);
		if (!raid.getTeam().isEmpty())
		{
			subtitle.setToolTipText("With " + String.join(", ", raid.getTeam()));
		}

		DamageBreakdown.Entry me = total.getLocal();
		String shareText = me == null ? "-" : Format.percent(me.getShare());
		if (me != null && !me.isTop() && total.getNamedCount() > 1)
		{
			shareText = "#" + total.getLocalRank() + "  " + shareText;
		}
		JLabel share = new JLabel(shareText, SwingConstants.RIGHT);
		share.setFont(FontManager.getRunescapeBoldFont());
		share.setForeground(me != null && me.isTop() ? Icons.GOLD : Color.WHITE);
		if (me != null && me.isTop())
		{
			share.setIcon(Icons.STAR);
			share.setToolTipText("Top damage");
		}

		JLabel status = outcomeLabel(raid, live);

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		header.add(column(title, subtitle), BorderLayout.CENTER);
		header.add(column(share, status), BorderLayout.EAST);
		return header;
	}

	private static String teamSize(int players)
	{
		switch (players)
		{
			case 2:
				return "Duo";
			case 3:
				return "Trio";
			default:
				return players + "-man";
		}
	}

	private static JLabel outcomeLabel(RaidRecord raid, boolean live)
	{
		JLabel label = small("", SUBTLE_TEXT);
		label.setHorizontalAlignment(SwingConstants.RIGHT);
		if (live)
		{
			label.setText("Live");
			label.setForeground(LIVE_COLOR);
			return label;
		}

		RaidOutcome outcome = raid.getOutcome();
		if (outcome == null)
		{
			return label;
		}
		label.setText(outcome.getDisplayName());
		label.setForeground(outcomeColor(outcome));
		if (outcome != RaidOutcome.COMPLETED && raid.getEndRoom() != null)
		{
			label.setToolTipText(outcome.getDisplayName() + " at " + raid.getEndRoom().getDisplayName());
		}
		return label;
	}

	private static Color outcomeColor(RaidOutcome outcome)
	{
		switch (outcome)
		{
			case COMPLETED:
				return LIVE_COLOR;
			case WIPED:
				return WIPED_COLOR;
			default:
				return LEFT_COLOR;
		}
	}

	private static JPanel buildBody(RaidRecord raid, boolean live, boolean bossOnly, DamageBreakdown total, Map<String, Color> colors)
	{
		JPanel body = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		body.setOpaque(false);

		if (raid.getRooms().isEmpty())
		{
			body.add(small("Waiting for the first hit...", SUBTLE_TEXT));
			return body;
		}

		RaidOutcome outcome = raid.getOutcome();
		for (RoomRecord room : raid.getRooms())
		{
			DamageBreakdown breakdown = DamageBreakdown.ofRoom(room, raid.getLocalName(), bossOnly);
			JLabel status;
			if (live && !room.isComplete())
			{
				status = small("live", LIVE_COLOR);
				status.setToolTipText("Room in progress");
			}
			else if (outcome != null && outcome != RaidOutcome.COMPLETED && room.getRoom() == raid.getEndRoom())
			{
				status = small(outcome.getDisplayName().toLowerCase() + " " + Format.ticks(room.getTicks()), outcomeColor(outcome));
				status.setToolTipText("The raid ended here");
			}
			else
			{
				status = small(Format.ticks(room.getTicks()), SUBTLE_TEXT);
				status.setToolTipText("Time from first to last hit");
			}
			body.add(section(room.getRoom().getDisplayName(), status, breakdown, colors,
				room.getDamage(), room.getBossDamage(), bossOnly));
		}

		if (raid.getRooms().size() > 1)
		{
			int all = 0;
			int boss = 0;
			for (RoomRecord room : raid.getRooms())
			{
				all += room.getDamage();
				boss += room.getBossDamage();
			}
			JPanel raidTotal = section("Raid total", small(Format.ticks(raid.getTicks()), SUBTLE_TEXT), total, colors,
				all, boss, bossOnly);
			raidTotal.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
				new EmptyBorder(5, 0, 0, 0)));
			body.add(raidTotal);
		}
		return body;
	}

	private static JPanel section(String name, JLabel status, DamageBreakdown breakdown, Map<String, Color> colors,
		int all, int boss, boolean bossOnly)
	{
		JPanel section = new JPanel(new DynamicGridLayout(0, 1, 0, 1));
		section.setOpaque(false);

		JLabel title = new JLabel(name);
		title.setFont(FontManager.getRunescapeFont());
		title.setForeground(Color.WHITE);

		JLabel totalLabel = small(Format.number(bossOnly ? boss : all), SUBTLE_TEXT);

		JPanel titleRow = new JPanel(new BorderLayout(4, 0));
		titleRow.setOpaque(false);
		titleRow.setToolTipText("Total " + Format.number(all) + " damage, " + Format.number(boss) + " to the boss");
		titleRow.add(title, BorderLayout.WEST);
		titleRow.add(totalLabel, BorderLayout.CENTER);
		titleRow.add(status, BorderLayout.EAST);
		section.add(titleRow);

		int max = 0;
		for (DamageBreakdown.Entry entry : breakdown.getEntries())
		{
			max = Math.max(max, entry.getDamage());
		}
		for (DamageBreakdown.Entry entry : breakdown.getEntries())
		{
			section.add(new DamageRow(entry, max, Palette.of(entry, colors)));
		}
		return section;
	}

	private static JPanel column(JLabel top, JLabel bottom)
	{
		JPanel column = new JPanel(new GridLayout(2, 1));
		column.setOpaque(false);
		column.add(top);
		column.add(bottom);
		return column;
	}

	private static JLabel small(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(color);
		return label;
	}

	static String summaryText(RaidRecord raid, boolean bossOnly)
	{
		StringBuilder sb = new StringBuilder();
		sb.append(raid.getRaid().getDisplayName())
			.append(" - ").append(Format.date(raid.getStartTime()));
		if (raid.getOutcome() != null)
		{
			sb.append(" - ").append(raid.getOutcome().getDisplayName());
			if (raid.getOutcome() != RaidOutcome.COMPLETED && raid.getEndRoom() != null)
			{
				sb.append(" at ").append(raid.getEndRoom().getDisplayName());
			}
		}
		sb.append(bossOnly ? " (boss damage)" : "").append('\n');
		for (RoomRecord room : raid.getRooms())
		{
			sb.append(room.getRoom().getDisplayName()).append(" (").append(Format.ticks(room.getTicks())).append("): ");
			appendEntries(sb, DamageBreakdown.ofRoom(room, raid.getLocalName(), bossOnly));
			sb.append('\n');
		}
		sb.append("Total: ");
		appendEntries(sb, DamageBreakdown.ofRaid(raid, bossOnly));
		return sb.toString();
	}

	private static void appendEntries(StringBuilder sb, DamageBreakdown breakdown)
	{
		boolean first = true;
		for (DamageBreakdown.Entry entry : breakdown.getEntries())
		{
			if (!first)
			{
				sb.append(" | ");
			}
			first = false;
			sb.append(entry.getName()).append(' ')
				.append(Format.number(entry.getDamage()))
				.append(" (").append(Format.percent(entry.getShare())).append(')');
			if (entry.isTop())
			{
				sb.append(" *");
			}
		}
	}
}

package com.raidingdamage.ui;

import com.raidingdamage.Format;
import com.raidingdamage.RaidingDamageConfig;
import com.raidingdamage.damage.DamageBreakdown;
import com.raidingdamage.damage.DamageHistory;
import com.raidingdamage.damage.RaidOutcome;
import com.raidingdamage.damage.RaidRecord;
import com.raidingdamage.raid.RaidType;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.IntConsumer;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class RaidingDamagePanel extends PluginPanel
{
	private static final String[] MODES = {"All damage", "Boss only"};
	private static final Color SUBTLE_TEXT = new Color(0x9A9A9A);

	private final DamageHistory history;
	private final RaidingDamageConfig config;

	private final JPanel filterRow = new JPanel(new BorderLayout());
	private final JPanel liveSection = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JPanel historyList = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JLabel historyTitle = new JLabel();
	private final JLabel statsLabel = new JLabel();

	private final Set<String> expanded = new HashSet<>();
	private RaidRecord live;
	private String liveExpandedId;
	private List<RaidRecord> raids = Collections.emptyList();
	private RaidType filter;
	private boolean bossOnly;

	@Inject
	RaidingDamagePanel(DamageHistory history, RaidingDamageConfig config)
	{
		this.history = history;
		this.config = config;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
		content.setOpaque(false);
		content.add(buildTitle());
		filterRow.setOpaque(false);
		content.add(filterRow);
		content.add(segmented(MODES, 0, i ->
		{
			bossOnly = i == 1;
			rebuildLive();
			rebuildHistory();
		}));

		liveSection.setOpaque(false);
		content.add(liveSection);
		content.add(buildHistoryHeader());
		historyList.setOpaque(false);
		content.add(historyList);

		add(content, BorderLayout.NORTH);
		updateRaidFilters();
		rebuildLive();
	}

	/**
	 * Show filter tabs only for the raids being tracked. With one or none tracked there's
	 * nothing to filter between, so the row is left empty.
	 */
	public void updateRaidFilters()
	{
		List<RaidType> tracked = new ArrayList<>();
		for (RaidType type : RaidType.values())
		{
			if (type.isTracked(config))
			{
				tracked.add(type);
			}
		}

		if (!tracked.contains(filter))
		{
			filter = null;
		}

		filterRow.removeAll();
		if (tracked.size() > 1)
		{
			String[] labels = new String[tracked.size() + 1];
			labels[0] = "All";
			for (int i = 0; i < tracked.size(); i++)
			{
				labels[i + 1] = tracked.get(i).getShortName();
			}
			int selected = filter == null ? 0 : tracked.indexOf(filter) + 1;
			filterRow.add(segmented(labels, selected, i ->
			{
				filter = i == 0 ? null : tracked.get(i - 1);
				rebuildHistory();
			}));
		}
		filterRow.revalidate();
		filterRow.repaint();
		rebuildHistory();
	}

	public void setLive(RaidRecord raid)
	{
		live = raid;
		if (raid != null && !raid.getId().equals(liveExpandedId))
		{
			// The current raid starts expanded; after that, respect whatever the user picks
			liveExpandedId = raid.getId();
			expanded.add(raid.getId());
		}
		rebuildLive();
	}

	public void setHistory(List<RaidRecord> raids)
	{
		this.raids = raids;
		rebuildHistory();
	}

	private JPanel buildTitle()
	{
		JLabel title = new JLabel("Raiding Damage");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);

		JPanel panel = new JPanel(new BorderLayout());
		panel.setOpaque(false);
		panel.add(title, BorderLayout.WEST);
		return panel;
	}

	private JPanel buildHistoryHeader()
	{
		historyTitle.setFont(FontManager.getRunescapeBoldFont());
		historyTitle.setForeground(Color.WHITE);

		JLabel clear = new JLabel("Clear");
		clear.setFont(FontManager.getRunescapeSmallFont());
		clear.setForeground(SUBTLE_TEXT);
		clear.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		clear.setToolTipText("Delete all recorded raids");
		clear.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				confirmClear();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				clear.setForeground(Color.WHITE);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				clear.setForeground(SUBTLE_TEXT);
			}
		});

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setOpaque(false);
		titleRow.add(historyTitle, BorderLayout.WEST);
		titleRow.add(clear, BorderLayout.EAST);

		statsLabel.setFont(FontManager.getRunescapeSmallFont());
		statsLabel.setForeground(SUBTLE_TEXT);

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.setBorder(new EmptyBorder(2, 0, 0, 0));
		header.add(titleRow, BorderLayout.NORTH);
		header.add(statsLabel, BorderLayout.SOUTH);
		return header;
	}

	private void rebuildLive()
	{
		liveSection.removeAll();
		if (live != null)
		{
			liveSection.add(card(live, true));
		}
		liveSection.revalidate();
		liveSection.repaint();
	}

	private void rebuildHistory()
	{
		historyList.removeAll();

		int shown = 0;
		int withDamage = 0;
		int tops = 0;
		int completed = 0;
		double shareSum = 0;
		for (RaidRecord raid : raids)
		{
			if (filter != null && raid.getRaid() != filter)
			{
				continue;
			}
			shown++;
			historyList.add(card(raid, false));
			completed += raid.getOutcome() == RaidOutcome.COMPLETED ? 1 : 0;

			DamageBreakdown.Entry me = DamageBreakdown.ofRaid(raid, bossOnly).getLocal();
			if (me != null)
			{
				withDamage++;
				shareSum += me.getShare();
				tops += me.isTop() ? 1 : 0;
			}
		}

		if (shown == 0)
		{
			JLabel empty = new JLabel("<html>No raids recorded yet.<br><br>Start fighting in the Theatre of Blood, "
				+ "Tombs of Amascut, Chambers of Xeric or The Fractured Archive and your damage will show up here, room by room.<br><br>"
				+ "Join a RuneLite party with your team to see everyone's damage, not just yours.</html>");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(SUBTLE_TEXT);
			empty.setBorder(new EmptyBorder(4, 2, 4, 2));
			historyList.add(empty);
		}

		historyTitle.setText("History (" + shown + ")");
		statsLabel.setText(withDamage == 0
			? ""
			: completed + "/" + shown + " completed - avg " + Format.percent(shareSum / withDamage)
				+ " - top " + tops + "x");
		statsLabel.setVisible(withDamage > 0);

		historyList.revalidate();
		historyList.repaint();
	}

	private RaidCard card(RaidRecord raid, boolean isLive)
	{
		String id = raid.getId();
		return new RaidCard(raid, isLive, expanded.contains(id), bossOnly,
			() -> toggle(id, isLive),
			() -> Toolkit.getDefaultToolkit().getSystemClipboard()
				.setContents(new StringSelection(RaidCard.summaryText(raid, bossOnly)), null),
			isLive ? null : () -> history.remove(id));
	}

	private void toggle(String id, boolean isLive)
	{
		if (!expanded.remove(id))
		{
			expanded.add(id);
		}
		if (isLive)
		{
			rebuildLive();
		}
		else
		{
			rebuildHistory();
		}
	}

	private void confirmClear()
	{
		if (raids.isEmpty())
		{
			return;
		}
		int result = JOptionPane.showConfirmDialog(this,
			"Delete all " + raids.size() + " recorded raids? This can't be undone.",
			"Clear raid history", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (result == JOptionPane.OK_OPTION)
		{
			history.clear();
		}
	}

	private static JPanel segmented(String[] labels, int initial, IntConsumer onSelect)
	{
		JPanel panel = new JPanel(new GridLayout(1, labels.length, 2, 0));
		panel.setOpaque(false);
		JLabel[] buttons = new JLabel[labels.length];
		int[] selected = {initial};

		for (int i = 0; i < labels.length; i++)
		{
			final int index = i;
			JLabel button = new JLabel(labels[i], SwingConstants.CENTER);
			button.setOpaque(true);
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			button.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					if (selected[0] != index)
					{
						selected[0] = index;
						styleSegments(buttons, index);
						onSelect.accept(index);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					if (selected[0] != index)
					{
						button.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
					}
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					styleSegments(buttons, selected[0]);
				}
			});
			buttons[i] = button;
			panel.add(button);
		}
		styleSegments(buttons, initial);
		return panel;
	}

	private static void styleSegments(JLabel[] buttons, int selected)
	{
		for (int i = 0; i < buttons.length; i++)
		{
			boolean on = i == selected;
			buttons[i].setBackground(on ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			buttons[i].setForeground(on ? Color.WHITE : SUBTLE_TEXT);
			buttons[i].setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 2, 0, on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR),
				new EmptyBorder(3, 0, 1, 0)));
		}
	}
}

package com.raidingdamage.ui;

import com.raidingdamage.damage.DamageBreakdown;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.util.Map;
import javax.swing.JComponent;

/**
 * Thin stacked bar showing everyone's share of a raid at a glance.
 */
class ShareBar extends JComponent
{
	private final DamageBreakdown breakdown;
	private final Map<String, Color> colors;

	ShareBar(DamageBreakdown breakdown, Map<String, Color> colors)
	{
		this.breakdown = breakdown;
		this.colors = colors;
		setPreferredSize(new Dimension(0, 3));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		int w = getWidth();
		int h = getHeight();
		g.setColor(Palette.BAR_BACKGROUND);
		g.fillRect(0, 0, w, h);

		if (breakdown.getTotal() == 0)
		{
			return;
		}

		// Local player first, so "your" segment always starts at the left edge
		int x = 0;
		for (int pass = 0; pass < 2; pass++)
		{
			for (DamageBreakdown.Entry entry : breakdown.getEntries())
			{
				if (entry.isLocal() != (pass == 0))
				{
					continue;
				}
				int width = (int) Math.round(entry.getShare() * w);
				g.setColor(Palette.of(entry, colors));
				g.fillRect(x, 0, Math.min(width, w - x), h);
				x += width;
			}
		}
	}
}

